def count_valid_salary_assignments(n, D, superiors):
    MOD = 10**9 + 7
    # Build adjacency list for the hierarchy
    adj = [[] for _ in range(n + 1)]
    for i in range(1, n):
        u = superiors[i - 1]
        adj[u].append(i + 1)

    # Dynamic programming: dp[u][s] = number of ways to assign salaries to subtree rooted at u with u's salary = s
    dp = [[0] * (D + 1) for _ in range(n + 1)]

    # Base case: leaf nodes (no subordinates)
    for u in range(1, n + 1):
        if not adj[u]:
            for s in range(1, D + 1):
                dp[u][s] = 1

    # Post-order traversal to fill dp
    stack = [(1, False)]
    while stack:
        u, visited = stack.pop()
        if not visited:
            stack.append((u, True))
            for v in reversed(adj[u]):
                stack.append((v, False))
        else:
            for s in range(1, D + 1):
                total = 1
                for v in adj[u]:
                    total *= sum(dp[v][1:s + 1])
                dp[u][s] = total % MOD

    return sum(dp[1][1:D + 1]) % MOD

